{
  "table": {
    "name": "gasstations",
    "purpose": "Dimension/master table with one row per gas station (5,716 stations). Each station is described by the retail chain it belongs to, its country (Czech Republic or Slovakia), and its market segment. It is referenced by transactions_1k.GasStationID, which records per-station sales transactions, so this table supplies the station attributes for those transactions."
  },
  "columns": {
    "ChainID": {
      "role": "foreign_key",
      "name": "ChainID",
      "description": "Identifier of the retail chain/brand that operates the gas station. 233 distinct chains with a heavily skewed distribution (chain 3: 1,462 stations; chain 2: 853; chain 33: 340; chain 1: 285), consistent with a few large chains and many small ones. No chain lookup table exists in this database, so the names behind the IDs are unknown. Note: the statistically accepted joins to transactions_1k.TransactionID and products.ProductID are spurious numeric coincidences (overlapping integer ranges), not real relationships.",
      "status": "resolved"
    },
    "Country": {
      "role": "category",
      "name": "Country",
      "description": "ISO 3166-1 alpha-3 code of the country where the gas station is located: 'CZE' = Czech Republic (4,836 stations, ~85%), 'SVK' = Slovakia (880 stations, ~15%).",
      "status": "resolved"
    },
    "GasStationID": {
      "role": "foreign_key",
      "name": "GasStationID",
      "description": "Surrogate primary key uniquely identifying one gas station (all 5,716 values distinct, no nulls, range 44–5772). Referenced by transactions_1k.GasStationID, linking each sales transaction to the station where it occurred.",
      "status": "resolved"
    },
    "Segment": {
      "role": "category",
      "name": "Segment",
      "description": "Market/positioning segment of the gas station, one of five categories: 'Premium' (1,428), 'Value for money' (597), 'Discount' (294), 'Noname' (1,005, presumably unbranded/independent stations), and 'Other' (2,392).",
      "status": "resolved"
    }
  }
}
